package dailychallenges;

public class FindKthBit {

    public char findKthBit(int n, int k) {
        if (n == 1) {
            return '0';
        }

        int length = (1 << n) - 1;
        int mid = length / 2 + 1;

        if (k == mid) {
            return '1';
        } else if (k < mid) {
            return findKthBit(n - 1, k);
        } else {
            char bit = findKthBit(n - 1, length - k + 1);
            return (bit == '0') ? '1' : '0';
        }
    }

    public static void main(String[] args) {
        FindKthBit obj = new FindKthBit();
        int n = 3, k = 5;
        System.out.println("n=" + n + ", k=" + k + " -> " + obj.findKthBit(n, k));

        n = 4;
        k = 11;
        System.out.println("n=" + n + ", k=" + k + " -> " + obj.findKthBit(n, k));
    }

}
